bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
docker inspect "$name" >/dev/null 2>&1 || { echo STK04_DM_CONTAINER=ABSENT; exit 61; }
if test "$(docker inspect -f '{{.State.Running}}' "$name")" != true;then echo STK04_DM_CONTAINER=NOT_RUNNING; exit 62;fi
echo STK04_DM_CONTAINER=RUNNING
docker logs --tail 100 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' && echo STK04_POLL_READY=OBSERVED || echo STK04_POLL_READY=NOT_IN_LAST_100_LOGS
docker exec "$name" node --input-type=module -e '
import pg from "pg";import {readFileSync} from "node:fs";
import {createTelegramBotApi} from "./src/telegram/botApi.mjs";
import {createCreatorTelegramFetch} from "./src/runtime/creatorEgress.mjs";
const env=process.env;
const pw=readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,"utf8").trim();
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,database:env.VIDEOBOT_DB_NAME,user:env.VIDEOBOT_DB_USER,password:pw,max:1,connectionTimeoutMillis:5000});
const outward=createCreatorTelegramFetch(globalThis.fetch);
try{
 const db=await pool.query("SELECT r.phase,r.kind,r.pack_name,r.file_unique_id,s.state->>\\u0027screen\\u0027 AS screen FROM videobot_sticker_registration_receipts r LEFT JOIN videobot_creator_sessions s ON s.owner_user_id=r.owner_user_id WHERE r.phase NOT IN (\\u0027registered\\u0027) ORDER BY r.updated_at DESC LIMIT 5");
 console.log("STK04_UNRESOLVED_RECEIPTS="+db.rows.length);
 const token=readFileSync(env.VIDEOBOT_TELEGRAM_TOKEN_FILE,"utf8").trim();
 const api=createTelegramBotApi({token,fetchImpl:outward.fetch,timeoutMs:15000});
 for(const [index,row] of db.rows.entries()){
  console.log("STK04_PENDING_"+index+"_PHASE="+row.phase);
  console.log("STK04_PENDING_"+index+"_SCREEN="+(row.screen??"UNKNOWN"));
  if(typeof row.pack_name!=="string"||!row.file_unique_id){console.log("STK04_PENDING_"+index+"_REMOTE=NO_RECEIPT");continue}
  try{
   const pack=await api("getStickerSet",{name:row.pack_name});
   console.log("STK04_PENDING_"+index+"_REMOTE="+(Array.isArray(pack?.stickers)&&pack.stickers.some(s=>s.file_unique_id===row.file_unique_id)?"ITEM_REGISTERED":"ITEM_NOT_FOUND"));
  }catch(e){console.log("STK04_PENDING_"+index+"_REMOTE=READBACK_UNAVAILABLE")}
 }
}catch(e){console.log("STK04_PENDING_DIAGNOSTIC=FAILED");process.exitCode=76;}
finally{await outward.close();await pool.end();}
'
